INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM207W96G', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two parallel lines are cut by a transversal. One of the alternate interior angles measures $63°$. What is the measure of the other alternate interior angle?', NULL, $lyceon_json$[{"key":"A","text":"$27°$"},{"key":"B","text":"$63°$"},{"key":"C","text":"$117°$"},{"key":"D","text":"$126°$"}]$lyceon_json$::jsonb, 'B', NULL, E'Alternate interior angles formed by parallel lines and a transversal are equal, so the other angle also measures $63°$. The distractor $27°$ results from an equation setup error of subtracting from $90°$ as if the angles were complementary. The distractor $117°$ comes from the concept gap of treating alternate interior angles as supplementary ($180° - 63° = 117°$). The distractor $126°$ results from an arithmetic slip of doubling $63°$ instead of recognizing the angles are equal.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20GHEO9', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'In right triangle $RST$, angle $T$ is a right angle, $RS = 61$, and $ST = 60$. What is the value of $\\tan(R)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{11}{61}$"},{"key":"B","text":"$\\frac{60}{61}$"},{"key":"C","text":"$\\frac{11}{60}$"},{"key":"D","text":"$\\frac{60}{11}$"}]$lyceon_json$::jsonb, 'D', NULL, E'Since angle $T = 90°$, side $RS = 61$ is the hypotenuse. First find $RT$: $RT^2 + ST^2 = RS^2$ gives $RT^2 + 3600 = 3721$, so $RT^2 = 121$ and $RT = 11$. Then $\\tan(R) = \\frac{\\text{opposite}}{\\text{adjacent}} = \\frac{ST}{RT} = \\frac{60}{11}$. The value $\\frac{11}{61}$ is $\\cos(R)$, a concept error of choosing the wrong ratio. The value $\\frac{60}{61}$ is $\\sin(R)$, also a wrong-ratio error. The value $\\frac{11}{60}$ is $\\tan(S)$, the tangent of the wrong angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20YX58I', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'If $5(x + 3) = 2x + 24$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$1$"},{"key":"B","text":"$3$"},{"key":"C","text":"$7$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'B', NULL, E'Distributing: $5x + 15 = 2x + 24$. Subtracting $2x$: $3x + 15 = 24$. Subtracting 15: $3x = 9$. Dividing by 3: $x = 3$. The distractor $1$ results from an arithmetic slip in the subtraction step (e.g., computing $3x = 3$ instead of $3x = 9$). The distractor $7$ arises from an equation setup error of forgetting to distribute to the constant: $5x + 3 = 2x + 24$ gives $3x = 21$ and $x = 7$. The distractor $9$ comes from partial reasoning that stops at $3x = 9$ and reports $9$ instead of dividing.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM211A873', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'The system of equations $7x - 3y = k$ and $-21x + 9y = 39$ has infinitely many solutions. What is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$-13$"},{"key":"B","text":"$-3$"},{"key":"C","text":"$13$"},{"key":"D","text":"$39$"}]$lyceon_json$::jsonb, 'A', NULL, E'For infinitely many solutions, the equations must be scalar multiples of each other. Multiplying $7x - 3y = k$ by $-3$ gives $-21x + 9y = -3k$. Setting $-3k = 39$ yields $k = -13$. The value $13$ results from ignoring the negative sign when dividing $39$ by $3$. The value $-3$ comes from incorrectly dividing $39$ by $-13$ and confusing the multiplier with $k$. The value $39$ assumes $k$ equals the constant in the second equation without accounting for the factor of $-3$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21IRG8L', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A bookstore purchased a shipment of novels for $\\$1,740$. After selling $65\\%$ of the novels at $\\$9$ each and the remaining $35\\%$ at $\\$6$ each, what was the total revenue if the shipment contained 400 novels?', NULL, $lyceon_json$[{"key":"A","text":"$\\$3,180$"},{"key":"B","text":"$\\$2,940$"},{"key":"C","text":"$\\$3,060$"},{"key":"D","text":"$\\$1,440$"}]$lyceon_json$::jsonb, 'A', NULL, E'Sixty-five percent of 400 is 260 novels sold at $\\$9$ each for $260 \\times 9 = \\$2{,}340$. The remaining $35\\%$ is 140 novels sold at $\\$6$ each for $140 \\times 6 = \\$840$. Total revenue is $\\$2{,}340 + \\$840 = \\$3{,}180$. The value $\\$3{,}060$ comes from an arithmetic slip when adding the two revenue amounts. The value $\\$2{,}940$ results from using $60\\%$ and $40\\%$ instead of the stated percentages. The value $\\$1{,}440$ is the result of computing only the discounted portion and ignoring the full-price portion.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21SBDAZ', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points $(-2, 11)$ and $(6, -13)$. What is the equation of this line in slope-intercept form?', NULL, $lyceon_json$[{"key":"A","text":"$y = -3x + 5$"},{"key":"B","text":"$y = 3x + 17$"},{"key":"C","text":"$y = -3x - 13$"},{"key":"D","text":"$y = 3x + 5$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $m = \\frac{-13 - 11}{6 - (-2)} = \\frac{-24}{8} = -3$. Using point $(-2, 11)$: $11 = -3(-2) + b$, so $11 = 6 + b$ and $b = 5$. The equation is $y = -3x + 5$. The equation $y = 3x + 17$ results from computing the slope as positive $3$ and then finding $b = 17$ from $11 = 3(-2) + b$. The equation $y = -3x - 13$ uses the correct slope but takes the $y$-coordinate of the second point as the $y$-intercept directly instead of computing $b$ through substitution. The equation $y = 3x + 5$ has the correct $y$-intercept but a positive slope from a sign error in the slope calculation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22209JU', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What positive value of $x$ satisfies $5x^2 - 45 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$3$"},{"key":"C","text":"$-3$"},{"key":"D","text":"$5$"}]$lyceon_json$::jsonb, 'B', NULL, E'Add $45$ to both sides: $5x^2 = 45$. Divide by $5$: $x^2 = 9$. Take the square root: $x = \\pm 3$. Since the question asks for the positive value, $x = 3$. The value $9$ stops at $x^2 = 9$ without taking the square root. The value $-3$ is the negative root. The value $5$ confuses the leading coefficient with the solution.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22GY9DM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A data set contains 11 values with a median of 37. If each value in the data set is multiplied by 4 and then 9 is subtracted from each result, what is the median of the new data set?', NULL, $lyceon_json$[{"key":"A","text":"$139$"},{"key":"B","text":"$112$"},{"key":"C","text":"$157$"},{"key":"D","text":"$148$"}]$lyceon_json$::jsonb, 'A', NULL, E'When every value in a data set undergoes the same linear transformation, the median is transformed the same way. The new median is $4(37) - 9 = 148 - 9 = 139$. The value $112$ results from subtracting 9 first and then multiplying by 4, reversing the order of operations: $4(37 - 9) = 4(28) = 112$. The value $157$ comes from adding 9 instead of subtracting it: $4(37) + 9 = 157$. The value $148$ results from forgetting to subtract 9 entirely and only multiplying by 4.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23W344R', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'Which of the following describes the end behavior of $f(x) = -2x^5 + 7x^3 - x + 4$?', NULL, $lyceon_json$[{"key":"A","text":"As $x \\to -\\infty$, $f(x) \\to \\infty$ and as $x \\to \\infty$, $f(x) \\to \\infty$"},{"key":"B","text":"As $x \\to -\\infty$, $f(x) \\to -\\infty$ and as $x \\to \\infty$, $f(x) \\to -\\infty$"},{"key":"C","text":"As $x \\to -\\infty$, $f(x) \\to -\\infty$ and as $x \\to \\infty$, $f(x) \\to \\infty$"},{"key":"D","text":"As $x \\to -\\infty$, $f(x) \\to \\infty$ and as $x \\to \\infty$, $f(x) \\to -\\infty$"}]$lyceon_json$::jsonb, 'D', NULL, E'The leading term is $-2x^5$. Because the degree is odd and the leading coefficient is negative, as $x \\to -\\infty$ the leading term $-2x^5 \\to \\infty$, and as $x \\to \\infty$ the leading term $-2x^5 \\to -\\infty$. The choice stating both directions tend to $\\infty$ reflects an even-degree positive-coefficient pattern. The choice stating both tend to $-\\infty$ reflects an even-degree negative-coefficient pattern. The choice stating $-\\infty$ then $\\infty$ reflects an odd-degree positive-coefficient sign error, ignoring the negative leading coefficient.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24GZYIE', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $\\frac{4x^2 - 16x}{4x}$ for $x \\neq 0$?', NULL, $lyceon_json$[{"key":"A","text":"$x - 4$"},{"key":"B","text":"$x^2 - 4x$"},{"key":"C","text":"$x - 16x$"},{"key":"D","text":"$4x - 16$"}]$lyceon_json$::jsonb, 'A', NULL, E'Splitting the fraction: $\\frac{4x^2 - 16x}{4x} = \\frac{4x^2}{4x} - \\frac{16x}{4x} = x - 4$. The distractor $x^2 - 4x$ results from dividing only by 4 instead of $4x$, giving $\\frac{4x^2}{4} - \\frac{16x}{4}$. The distractor $x - 16x$ comes from an arithmetic slip of dividing $16x$ by only $x$ in one term and by $4x$ in another. The distractor $4x - 16$ results from dividing by $x$ alone rather than $4x$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM256D0JX', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'A mechanic charges a flat diagnostic fee of $\\$37$ plus $\\$68$ per hour of labor. If the total bill for a repair was $\\$377$, how many hours of labor were required?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$5$"},{"key":"C","text":"$6$"},{"key":"D","text":"$5.5$"}]$lyceon_json$::jsonb, 'B', NULL, E'The equation is $37 + 68h = 377$. Subtracting 37 from both sides gives $68h = 340$. Dividing both sides by 68 yields $h = 5$. The value 4 results from a subtraction error that produces 272 instead of 340. The value 6 comes from omitting the diagnostic fee and computing $377 \\div 68 \\approx 5.54$, then rounding up to 6. The value 5.5 results from a division error when computing $340 \\div 68$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26V0GXY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'grid_in', E'A machine fills $13$ bottles every $4$ minutes. At this constant rate, how many bottles does the machine fill in $28$ minutes?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '91', ARRAY['91'], E'The machine fills $13$ bottles every $4$ minutes, so the rate is $\\frac{13}{4}$ bottles per minute. In $28$ minutes, the machine fills $\\frac{13}{4} \\times 28 = \\frac{364}{4} = 91$ bottles.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26X3D0C', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The linear function $f$ satisfies $f(3) = 23$ and $f(11) = 63$. A second linear function $g$ has a $y$-intercept of $48$ and decreases by $3$ for every increase of $1$ in $x$. For what value of $x$ does $f(x) = g(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-5$"},{"key":"B","text":"$20$"},{"key":"C","text":"$8$"},{"key":"D","text":"$5$"}]$lyceon_json$::jsonb, 'D', NULL, E'The slope of $f$ is $\\frac{63 - 23}{11 - 3} = \\frac{40}{8} = 5$. Using $f(3) = 23$: $23 = 5(3) + b$, so $b = 8$ and $f(x) = 5x + 8$. The function $g$ has slope $-3$ and $y$-intercept $48$, so $g(x) = -3x + 48$. Setting $f(x) = g(x)$: $5x + 8 = -3x + 48$, giving $8x = 40$ and $x = 5$. The value $-5$ results from a sign error when combining the $x$ terms. The value $20$ comes from using $g(x) = 3x + 48$ with a positive slope instead of $-3$, yielding $2x = 40$ and $x = 20$. The value $8$ comes from dividing $40$ by the slope of $f$ alone ($40 \\div 5 = 8$) instead of dividing by the combined coefficient $8$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27DSE2R', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the slope of the line represented by $6x + 3y = 15$?', NULL, $lyceon_json$[{"key":"A","text":"$-2$"},{"key":"B","text":"$-\\frac{1}{2}$"},{"key":"C","text":"$2$"},{"key":"D","text":"$5$"}]$lyceon_json$::jsonb, 'A', NULL, E'Solving for $y$: $3y = -6x + 15$, so $y = -2x + 5$. The slope is $-2$. The distractor $-\\frac{1}{2}$ comes from an equation setup error of inverting the coefficient ratio, computing $-\\frac{3}{6}$ instead of $-\\frac{6}{3}$. The distractor $2$ is a sign error from dropping the negative when dividing $-6$ by $3$. The distractor $5$ results from a concept gap of identifying the $y$-intercept as the slope.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27QN04M', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle has its center at $(-4, 7)$ and passes through the point $(1, 7)$. Which of the following is the equation of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$(x + 4)^2 + (y - 7)^2 = 25$"},{"key":"B","text":"$(x - 4)^2 + (y + 7)^2 = 25$"},{"key":"C","text":"$(x + 4)^2 + (y - 7)^2 = 5$"},{"key":"D","text":"$(x - 1)^2 + (y - 7)^2 = 25$"}]$lyceon_json$::jsonb, 'A', NULL, E'The radius is the distance from the center $(-4, 7)$ to $(1, 7)$: $r = |1 - (-4)| = 5$. The standard form is $(x - h)^2 + (y - k)^2 = r^2$, so $(x + 4)^2 + (y - 7)^2 = 25$. The equation $(x - 4)^2 + (y + 7)^2 = 25$ reverses the signs of the center coordinates, a sign error. The equation with $= 5$ uses the radius instead of the squared radius, a concept error. The equation $(x - 1)^2 + (y - 7)^2 = 25$ uses the given point $(1, 7)$ as the center instead of $(-4, 7)$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27WCJO4', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A bakery sells muffins and scones. On Saturday, 3 muffins and 5 scones cost $\\$37$. On Sunday, 3 muffins and 2 scones cost $\\$22$. What is the cost, in dollars, of one muffin?', NULL, $lyceon_json$[{"key":"A","text":"$\\$4$"},{"key":"B","text":"$\\$5$"},{"key":"C","text":"$\\$6$"},{"key":"D","text":"$\\$7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Let $m$ be the cost of a muffin and $s$ the cost of a scone. The system is $3m + 5s = 37$ and $3m + 2s = 22$. Subtracting the second from the first gives $3s = 15$, so $s = 5$. Substituting into $3m + 2(5) = 22$ gives $3m = 12$, so $m = 4$. The value $\\$5$ is the price of a scone, not a muffin. The value $\\$6$ results from an arithmetic error such as computing $22 - 10 = 12$ then dividing by $2$ instead of $3$. The value $\\$7$ arises from incorrectly dividing $22$ by $3$ and rounding up.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27ZYDFA', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A tutoring center charges a flat fee plus an hourly rate. Center P charges $\\$40$ plus $\\$29$ per hour, while Center Q charges $\\$85$ plus $\\$17$ per hour. For how many complete hours of tutoring is Center P strictly less expensive than Center Q?', NULL, $lyceon_json$[{"key":"A","text":"$1$ hour, $2$ hours, or $3$ hours"},{"key":"B","text":"$1$ hour or $2$ hours only"},{"key":"C","text":"$1$ hour, $2$ hours, $3$ hours, or $4$ hours"},{"key":"D","text":"Any number of hours greater than $0$"}]$lyceon_json$::jsonb, 'A', NULL, E'Center P costs $40 + 29h$ and Center Q costs $85 + 17h$. Setting $40 + 29h < 85 + 17h$ gives $12h < 45$, so $h < 3.75$. Since $h$ must be a positive integer, the valid values are $h = 1, 2, 3$. At $h = 4$, Center P costs $40 + 116 = 156$ and Center Q costs $85 + 68 = 153$, so Center P is more expensive. The option listing only $1$ and $2$ hours excludes the valid value $h = 3$. The option including $4$ hours incorrectly treats $h < 3.75$ as $h \\leq 4$. The option claiming any positive number of hours ignores that the rates eventually make Center P more expensive.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2947615', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A city council conducted a random survey of 600 residents and found that $43\\%$ support a proposed park renovation, with a margin of error of $4\\%$. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $43\\%$ of all city residents support the renovation."},{"key":"B","text":"Between $39\\%$ and $47\\%$ of all city residents are plausibly supportive of the renovation."},{"key":"C","text":"Between $39\\%$ and $47\\%$ of the 600 surveyed residents support the renovation."},{"key":"D","text":"No more than $47\\%$ of the city residents could support the renovation."}]$lyceon_json$::jsonb, 'B', NULL, E'A margin of error of $4\\%$ around a sample proportion of $43\\%$ produces a confidence interval of $39\\%$ to $47\\%$ for the true population proportion. The statement that exactly $43\\%$ support it ignores sampling variability. The statement restricting the interval to the 600 surveyed residents misapplies the interval, which estimates the population parameter, not the sample statistic. The claim that no more than $47\\%$ could support it treats the upper bound as an absolute maximum rather than a plausible range limit.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29X3BO5', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $\\frac{5x^2 + 23x + 12}{5x + 3} = x + k$, what is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$-4$"},{"key":"D","text":"$-3$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factor $5x^2 + 23x + 12$. We need two numbers whose product is $5 \\cdot 12 = 60$ and whose sum is $23$: those are $20$ and $3$. So $5x^2 + 20x + 3x + 12 = 5x(x + 4) + 3(x + 4) = (5x + 3)(x + 4)$. Dividing by $(5x + 3)$ gives $x + 4$, so $k = 4$. The value $3$ comes from confusing the constant $3$ in the factor $(5x + 3)$ with $k$. The values $-4$ and $-3$ apply an incorrect sign to the result.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AEKMMQ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylinder has a radius of $3$ inches and a height of $11$ inches. Which of the following is the volume, in cubic inches, of this cylinder?', NULL, $lyceon_json$[{"key":"A","text":"$33\\pi$"},{"key":"B","text":"$66\\pi$"},{"key":"C","text":"$99\\pi$"},{"key":"D","text":"$297\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The volume of a cylinder is $V = \\pi r^2 h = \\pi (3)^2 (11) = 99\\pi$ cubic inches. The value $33\\pi$ comes from using $\\pi r h$ instead of $\\pi r^2 h$, an equation-setup error of forgetting to square the radius. The value $66\\pi$ comes from using the lateral surface area formula $2\\pi r h = 2\\pi(3)(11) = 66\\pi$, a concept error. The value $297\\pi$ comes from cubing the radius instead of squaring it: $\\pi(27)(11) = 297\\pi$, an arithmetic slip.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AIHU3O', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A swimming pool is being drained at a constant rate. After 3 hours, the pool contains 4,700 gallons of water, and after 8 hours, it contains 2,200 gallons. What is the rate of change, in gallons per hour?', NULL, $lyceon_json$[{"key":"A","text":"$500$"},{"key":"B","text":"$-600$"},{"key":"C","text":"$-500$"},{"key":"D","text":"$600$"}]$lyceon_json$::jsonb, 'C', NULL, E'The rate of change is $\\frac{2200 - 4700}{8 - 3} = \\frac{-2500}{5} = -500$ gallons per hour. The negative sign indicates the pool is losing water. The value $500$ drops the negative sign, failing to reflect that the quantity is decreasing. The value $-600$ results from dividing $-2500$ by an incorrect time difference. The value $600$ compounds both errors by using the wrong interval and ignoring the sign.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AXD5SV', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A right circular cone has a slant height of $17$ centimeters and a base radius of $8$ centimeters. What is the volume, in cubic centimeters, of the cone?', NULL, $lyceon_json$[{"key":"A","text":"$320\\pi$"},{"key":"B","text":"$\\frac{1088\\pi}{3}$"},{"key":"C","text":"$960\\pi$"},{"key":"D","text":"$1088\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'First find the height using the Pythagorean theorem with the slant height and radius: $h^2 + 8^2 = 17^2$ gives $h^2 = 289 - 64 = 225$, so $h = 15$. The volume of a cone is $V = \\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(64)(15) = \\frac{960\\pi}{3} = 320\\pi$. The value $\\frac{1088\\pi}{3}$ results from using the slant height $17$ instead of the actual height $15$: $\\frac{1}{3}\\pi(64)(17)$, a concept error. The value $960\\pi$ uses the correct height but omits the $\\frac{1}{3}$ factor: $\\pi(64)(15) = 960\\pi$, a partial-reasoning error. The value $1088\\pi$ both uses the slant height and omits the $\\frac{1}{3}$ factor: $\\pi(64)(17) = 1088\\pi$, an equation-setup error.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AZ7F59', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A plumber charges a service call fee plus a constant rate per minute of work. The total charge in dollars for a job lasting $m$ minutes is modeled by $C(m) = 2.75m + 55$. Which statement best interprets the number $2.75$ in this context?', NULL, $lyceon_json$[{"key":"A","text":"The plumber charges $\\$2.75$ per minute of work."},{"key":"B","text":"The plumber charges a flat fee of $\\$2.75$ for each service call."},{"key":"C","text":"Each additional minute of work reduces the total charge by $\\$2.75$."},{"key":"D","text":"The total charge for a 1-minute job is $\\$2.75$."}]$lyceon_json$::jsonb, 'A', NULL, E'In the linear function $C(m) = 2.75m + 55$, the coefficient $2.75$ is the rate of change, representing the additional cost for each minute of work. Interpreting $2.75$ as a flat fee confuses the slope with the $y$-intercept; the flat fee is $\\$55$. The claim that each minute reduces the charge contradicts the positive slope. The total charge for a 1-minute job is $C(1) = 2.75 + 55 = 57.75$, not $\\$2.75$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BOPRSC', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'The equation $x^2 + y^2 - 14x + 6y + 33 = 0$ defines a circle in the $xy$-plane. What is the radius of this circle?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{33}$"},{"key":"B","text":"$5$"},{"key":"C","text":"$25$"},{"key":"D","text":"$\\sqrt{58}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Complete the square: $(x^2 - 14x + 49) + (y^2 + 6y + 9) = -33 + 49 + 9$, which gives $(x - 7)^2 + (y + 3)^2 = 25$. Since $r^2 = 25$, the radius is $r = 5$. The value $\\sqrt{33}$ results from incorrectly taking the square root of the constant $33$ without completing the square. The value $25$ is $r^2$, not $r$, a concept error of confusing the squared radius with the radius. The value $\\sqrt{58}$ comes from adding $49 + 9 = 58$ but neglecting to subtract $33$, an arithmetic slip.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BVSIV1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'Researchers at a university wanted to determine whether a new tutoring method improves exam scores. They randomly assigned 150 students to either receive the new tutoring method or continue with the standard method. At the end of the semester, the group using the new method had significantly higher average exam scores. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The new tutoring method likely caused the improvement in exam scores for the students in the study."},{"key":"B","text":"The new tutoring method will improve exam scores for all university students."},{"key":"C","text":"There is an association between the tutoring method and exam scores, but a causal conclusion cannot be drawn."},{"key":"D","text":"The students who chose the new method were already stronger students."}]$lyceon_json$::jsonb, 'A', NULL, E'Because the researchers randomly assigned students to the two groups, this is a randomized experiment. Random assignment controls for confounding variables, allowing a causal conclusion about the treatment effect for the study participants. The claim that the method will improve scores for all university students overgeneralizes beyond the study population. The claim that only an association can be drawn ignores that random assignment, not merely observation, was used, which does support causation. The claim about students choosing the method contradicts the study design, which used random assignment rather than self-selection.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CXR77P', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'If $x^2 - 17x + 52 = 0$, what is the sum of the solutions?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17', ARRAY['17'], E'By Vieta''s formulas, for a quadratic $x^2 + bx + c = 0$, the sum of the roots equals $-b$. Here $b = -17$, so the sum is $17$. Alternatively, factoring gives $(x - 4)(x - 13) = 0$, so $x = 4$ or $x = 13$, and $4 + 13 = 17$.', NULL, NULL, 'draft', 1, 65, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D39Z6B', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A florist sells roses and lilies. A bouquet of 6 roses and 11 lilies costs $\\$59$, and a bouquet of 6 roses and 4 lilies costs $\\$38$. What is the cost, in dollars, of one lily?', NULL, $lyceon_json$[{"key":"A","text":"$\\$2$"},{"key":"B","text":"$\\$3$"},{"key":"C","text":"$\\$4$"},{"key":"D","text":"$\\$5$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $r$ be the cost of a rose and $l$ the cost of a lily. The system is $6r + 11l = 59$ and $6r + 4l = 38$. Subtracting the second from the first gives $7l = 21$, so $l = 3$. The value $\\$2$ results from an arithmetic slip such as dividing $21$ by $11$ and rounding. The value $\\$4$ comes from finding $r$ instead: substituting $l = 3$ gives $6r = 38 - 12 = 26$, but then mistakenly reporting $26 \\div 6 \\approx 4$ as the lily price. The value $\\$5$ arises from incorrectly subtracting $59 - 38 = 21$ and then dividing by $4$ instead of $7$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DLEWNI', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'A quadratic function $f$ is defined by $f(x) = ax^2 + bx + c$, where $a$, $b$, and $c$ are constants. The parabola $y = f(x)$ has its vertex at $(4, -7)$ and passes through the point $(0, 41)$. What is the value of $b$?', NULL, $lyceon_json$[{"key":"A","text":"$-24$"},{"key":"B","text":"$-8$"},{"key":"C","text":"$8$"},{"key":"D","text":"$24$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using vertex form, $f(x) = a(x - 4)^2 - 7$. Substituting $(0, 41)$: $a(0 - 4)^2 - 7 = 41$, so $16a = 48$ and $a = 3$. Expanding: $f(x) = 3(x^2 - 8x + 16) - 7 = 3x^2 - 24x + 48 - 7 = 3x^2 - 24x + 41$. Thus $b = -24$. The value $-8$ comes from partial reasoning that takes the $-8x$ coefficient from expanding $(x - 4)^2 = x^2 - 8x + 16$ without multiplying by $a = 3$. The value $8$ results from a concept gap of taking the absolute value of that same unexpanded coefficient. The value $24$ is a sign error from dropping the negative sign in $-24$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FB9S5V', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'The equation $a(3x + 5) = 9x + b$ has infinitely many solutions. Which of the following must be true?', NULL, $lyceon_json$[{"key":"A","text":"$a = 3$ and $b = 5$"},{"key":"B","text":"$a = 9$ and $b = 5$"},{"key":"C","text":"$a = 9$ and $b = 15$"},{"key":"D","text":"$a = 3$ and $b = 15$"}]$lyceon_json$::jsonb, 'D', NULL, E'For infinitely many solutions, the equation must be an identity. Expanding the left side gives $3ax + 5a = 9x + b$. Matching the $x$ coefficients: $3a = 9$, so $a = 3$. Matching the constants: $5a = b$, so $b = 5(3) = 15$. Therefore $a = 3$ and $b = 15$. The pair $a = 3, b = 5$ incorrectly sets $b$ equal to the original constant 5 without multiplying by $a$. The pair $a = 9, b = 5$ confuses the coefficient of $x$ on the right side with the value of $a$, ignoring the factor of 3. The pair $a = 9, b = 15$ also sets $a$ to 9 without dividing by 3.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FKSSEB', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'The function $g$ is defined by $g(x) = \\frac{7x - 19}{3}$. For what value of $x$ does $g(x) = 13$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{20}{7}$"},{"key":"B","text":"$8$"},{"key":"C","text":"$\\frac{32}{7}$"},{"key":"D","text":"$\\frac{58}{7}$"}]$lyceon_json$::jsonb, 'D', NULL, E'Setting $g(x) = 13$: $\\frac{7x - 19}{3} = 13$. Multiplying both sides by 3 gives $7x - 19 = 39$. Adding 19 to both sides gives $7x = 58$. Dividing by 7 yields $x = \\frac{58}{7}$. The value $\\frac{20}{7}$ comes from subtracting 19 from 39 to get 20 instead of adding. The value $8$ results from rounding $\\frac{58}{7} \\approx 8.29$ to the nearest integer. The value $\\frac{32}{7}$ comes from skipping the multiplication by 3 and solving $7x - 19 = 13$ to get $7x = 32$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HA9O7P', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'A student has a budget of at most $\\$120$ for books. Each book costs $\\$15$. Which inequality represents the number of books $n$ the student can buy?', NULL, $lyceon_json$[{"key":"A","text":"$n \\leq 8$"},{"key":"B","text":"$n < 8$"},{"key":"C","text":"$n \\geq 8$"},{"key":"D","text":"$n \\leq 120$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is $15n$ and the budget is at most $\\$120$, so $15n \\leq 120$, giving $n \\leq 8$. The distractor $n < 8$ results from a concept gap of using strict inequality when ''at most'' means $\\leq$, which would exclude exactly 8 books. The distractor $n \\geq 8$ reverses the inequality direction. The distractor $n \\leq 120$ comes from misreading the question and using the budget as the bound on $n$ without dividing by the price.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HGN5IO', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{4x^2 - 25}{2x + 5}$?', NULL, $lyceon_json$[{"key":"A","text":"$2x + 5$"},{"key":"B","text":"$2x - 5$"},{"key":"C","text":"$4x - 5$"},{"key":"D","text":"$2x^2 - 5$"}]$lyceon_json$::jsonb, 'B', NULL, E'The numerator $4x^2 - 25$ is a difference of squares: $(2x)^2 - 5^2 = (2x + 5)(2x - 5)$. Dividing by $(2x + 5)$ cancels the common factor, leaving $2x - 5$. The expression $2x + 5$ selects the wrong factor after cancellation. The expression $4x - 5$ incorrectly simplifies the squared term without proper factoring. The expression $2x^2 - 5$ attempts to divide term-by-term without factoring.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HWAVSL', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $f(x) = a(x - h)^2 + k$ has its vertex at $(3, -4)$ and passes through the point $(6, 23)$. What is the value of $a$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{1}{3}$"},{"key":"B","text":"$3$"},{"key":"C","text":"$9$"},{"key":"D","text":"$27$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting the vertex $(3, -4)$ gives $f(x) = a(x - 3)^2 - 4$. Using the point $(6, 23)$: $a(6 - 3)^2 - 4 = 23$, so $9a - 4 = 23$, which yields $9a = 27$ and $a = 3$. The value $\\frac{1}{3}$ arises from a concept gap of using $(x + h)^2$ instead of $(x - h)^2$, giving $a(6 + 3)^2 - 4 = 23$ and $81a = 27$. The value $9$ results from an equation setup error of forgetting to square the binomial: $a(6 - 3) - 4 = 23$ gives $3a = 27$. The value $27$ comes from partial reasoning where the student solves $9a = 27$ but reports $27$ instead of dividing.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HWVJP0', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'grid_in', E'The function $f$ is defined by $f(x) = 2(x - 7)^2 - 18$. What is the minimum value of $f(x)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-18', ARRAY['-18'], E'Since $f(x) = 2(x - 7)^2 - 18$ is in vertex form $a(x - h)^2 + k$ with $a = 2 > 0$, the parabola opens upward and has its minimum at the vertex $(7, -18)$. The minimum value of $f(x)$ is $-18$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HZ71HW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A ceramic studio uses $\\frac{7}{4}$ pounds of clay to produce 3 identical bowls. At this rate, how many pounds of clay are needed to produce 54 bowls?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{63}{2}$"},{"key":"B","text":"$\\frac{189}{7}$"},{"key":"C","text":"$\\frac{126}{4}$"},{"key":"D","text":"$\\frac{189}{4}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The rate is $\\frac{7}{4}$ pounds per 3 bowls, or $\\frac{7}{12}$ pounds per bowl. For 54 bowls: $54 \\times \\frac{7}{12} = \\frac{378}{12} = \\frac{63}{2}$. The value $\\frac{189}{7}$ results from incorrectly dividing 54 by 2 then multiplying by 7 without proper unit conversion. The value $\\frac{126}{4}$ comes from multiplying $\\frac{7}{4}$ by 18 but using 18 instead of the correct multiplier. The value $\\frac{189}{4}$ results from multiplying $\\frac{7}{4}$ by 27, treating the ratio as pounds per 2 bowls rather than per 3.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I1LPE7', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $DEF$, the measure of angle $D$ is $3$ times the measure of angle $E$, and the measure of angle $F$ is $20°$ more than the measure of angle $E$. What is the measure, in degrees, of angle $D$?', NULL, $lyceon_json$[{"key":"A","text":"$32$"},{"key":"B","text":"$96$"},{"key":"C","text":"$108$"},{"key":"D","text":"$120$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let the measure of angle $E$ be $x$. Then angle $D = 3x$ and angle $F = x + 20$. Since the angles of a triangle sum to $180°$: $x + 3x + (x + 20) = 180$, so $5x + 20 = 180$, giving $5x = 160$ and $x = 32$. Therefore angle $D = 3(32) = 96°$. The value $32$ is the measure of angle $E$, not $D$, a partial-reasoning error. The value $108$ comes from omitting the $+20$ term in the equation ($5x = 180$ gives $x = 36$, then $3 \\times 36 = 108$), an equation-setup error. The value $120$ comes from an arithmetic slip in computing $180 - 20 = 200$ instead of $160$, leading to $x = 40$ and $3 \\times 40 = 120$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IQWAAV', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is an exponential function of the form $f(x) = a \\cdot b^x$, where $a$ and $b$ are positive constants. If $f(1) = 6$ and $f(4) = 162$, what is the value of $f(0)$?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$2$"},{"key":"C","text":"$6$"},{"key":"D","text":"$18$"}]$lyceon_json$::jsonb, 'B', NULL, E'From $f(1) = ab = 6$ and $f(4) = ab^4 = 162$, dividing gives $b^3 = \\frac{162}{6} = 27$, so $b = 3$. Then $a \\cdot 3 = 6$, giving $a = 2$. Therefore $f(0) = 2 \\cdot 3^0 = 2 \\cdot 1 = 2$. The value $0$ results from the concept gap of believing $b^0 = 0$ rather than $b^0 = 1$. The value $6$ comes from partial reasoning that $f(0)$ equals $f(1) = 6$ without accounting for the base change. The value $18$ arises from an equation setup error of dividing in the wrong order ($b^3 = 6/162 = 1/27$, so $b = 1/3$) and then computing $a(1/3) = 6$ giving $a = 18$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KE4QTJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'In a survey of 200 employees at a company, 84 reported exercising regularly and 52 reported following a specific diet plan. Of those who exercise regularly, 29 also follow the diet plan. If one employee is selected at random from those who exercise regularly, what is the probability that this employee also follows the diet plan?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{29}{200}$"},{"key":"B","text":"$\\frac{29}{84}$"},{"key":"C","text":"$\\frac{29}{52}$"},{"key":"D","text":"$\\frac{84}{200}$"}]$lyceon_json$::jsonb, 'B', NULL, E'This is a conditional probability question. Given that the employee exercises regularly, the sample space is restricted to the 84 employees who exercise. Of those 84, 29 also follow the diet plan. So the probability is $\\frac{29}{84}$. The value $\\frac{29}{200}$ uses the total number of employees as the denominator instead of conditioning on exercising. The value $\\frac{29}{52}$ incorrectly uses the number of diet-plan followers as the denominator. The value $\\frac{84}{200}$ gives the probability of exercising regularly, which is not what the question asks.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KF1SOX', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'For what value of $c$ does the system $y = 2x^2 + 5x + c$ and $y = 9x - 3$ have exactly one real solution?', NULL, $lyceon_json$[{"key":"A","text":"$-1$"},{"key":"B","text":"$1$"},{"key":"C","text":"$3$"},{"key":"D","text":"$-3$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting the equations equal: $2x^2 + 5x + c = 9x - 3$, which simplifies to $2x^2 - 4x + (c + 3) = 0$. For exactly one solution, the discriminant equals zero: $(-4)^2 - 4(2)(c + 3) = 0$. This gives $16 - 8(c + 3) = 0$, so $16 - 8c - 24 = 0$, thus $-8 - 8c = 0$ and $c = -1$. The value $1$ applies an incorrect sign when solving for $c$. The value $3$ comes from setting $c + 3 = 0$ instead of using the discriminant. The value $-3$ results from an arithmetic error in expanding $-8(c + 3)$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L5GVUZ', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $(3x^2 - 11x + 4) - (x^2 + 7x - 9)$?', NULL, $lyceon_json$[{"key":"A","text":"$2x^2 - 4x - 5$"},{"key":"B","text":"$2x^2 - 18x + 13$"},{"key":"C","text":"$4x^2 - 18x + 13$"},{"key":"D","text":"$2x^2 - 18x - 5$"}]$lyceon_json$::jsonb, 'B', NULL, E'Distributing the negative sign: $3x^2 - 11x + 4 - x^2 - 7x + 9$. Combining like terms: $(3 - 1)x^2 = 2x^2$, $(-11 - 7)x = -18x$, and $4 + 9 = 13$. The result is $2x^2 - 18x + 13$. The expression $2x^2 - 4x - 5$ fails to distribute the negative sign to $7x$ and $-9$. The expression $4x^2 - 18x + 13$ adds the $x^2$ coefficients instead of subtracting. The expression $2x^2 - 18x - 5$ incorrectly computes $4 - 9$ instead of $4 + 9$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LEUPRW', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is the positive solution of $x^2 = 121$?', NULL, $lyceon_json$[{"key":"A","text":"$61$"},{"key":"B","text":"$-11$"},{"key":"C","text":"$11$"},{"key":"D","text":"$22$"}]$lyceon_json$::jsonb, 'C', NULL, E'Taking the square root of both sides gives $x = \\pm 11$. Since the question asks for the positive solution, $x = 11$. The value $61$ incorrectly halves $121$ and rounds. The value $-11$ is the negative root, not the positive one. The value $22$ doubles the square root instead of reporting it directly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 35, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M1L4TA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A store marks up the wholesale price of a jacket by $60\\%$ to set the retail price. During a sale, the store offers a $25\\%$ discount on the retail price. After the sale, a local tax of $7\\%$ is applied to the discounted price. If a customer pays $\\$128.40$ total including tax, what was the wholesale price of the jacket?', NULL, $lyceon_json$[{"key":"A","text":"$\\$100$"},{"key":"B","text":"$\\$80$"},{"key":"C","text":"$\\$96$"},{"key":"D","text":"$\\$120$"}]$lyceon_json$::jsonb, 'A', NULL, E'Let $w$ be the wholesale price. The retail price is $1.6w$. After a $25\\%$ discount, the price is $0.75 \\times 1.6w = 1.2w$. With $7\\%$ tax, the total is $1.07 \\times 1.2w = 1.284w$. Setting $1.284w = 128.40$ gives $w = \\frac{128.40}{1.284} = 100$. The wholesale price is $\\$100$. The value $\\$80$ results from applying the discount and tax but forgetting the markup, solving $1.07 \\times 0.75w = 128.40$ incorrectly. The value $\\$96$ comes from dividing by $1.07$ but then not properly reversing the markup and discount steps. The value $\\$120$ results from dividing $128.40$ only by $1.07$ and treating that as the wholesale price, ignoring the markup and discount entirely.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M522V2', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A shipping container can hold at most 1,900 pounds. Each box of machinery weighs 65 pounds and each box of fabric weighs 40 pounds. If $m$ boxes of machinery and $f$ boxes of fabric are loaded, which inequality models this constraint?', NULL, $lyceon_json$[{"key":"A","text":"$65m + 40f \\leq 1,900$"},{"key":"B","text":"$40m + 65f \\leq 1,900$"},{"key":"C","text":"$65m + 40f \\geq 1,900$"},{"key":"D","text":"$65m + 40f < 1,900$"}]$lyceon_json$::jsonb, 'A', NULL, E'Each machinery box contributes 65 pounds and each fabric box contributes 40 pounds, so the total weight is $65m + 40f$. Since the container holds at most 1,900 pounds, the inequality is $65m + 40f \\leq 1{,}900$. The option $40m + 65f \\leq 1{,}900$ reverses the per-unit weights, assigning 40 to machinery and 65 to fabric. The option using $\\geq$ reverses the direction of the inequality, requiring the load to exceed capacity. The option using strict $<$ excludes loading exactly 1,900 pounds, which is permitted by "at most."', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M5LAWB', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'If $x^2 + 6x = 40$, what is the positive value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$5$"},{"key":"C","text":"$6$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewriting: $x^2 + 6x - 40 = 0$. Factoring: $(x + 10)(x - 4) = 0$, so $x = -10$ or $x = 4$. The positive value is $4$. The distractor $5$ results from an equation setup error such as trying $x(x + 6) = 40$ and guessing $5 \\cdot 11 = 55 \\neq 40$ but selecting 5 anyway. The distractor $6$ comes from the concept gap of treating the coefficient of $x$ as the answer. The distractor $10$ results from partial reasoning that finds $x = -10$ and drops the negative sign.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MUE97I', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'In right triangle $JKL$, angle $L$ is a right angle, $JK = 41$, and $KL = 40$. What is the length of $JL$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'Since angle $L$ is the right angle, $JK$ is the hypotenuse. By the Pythagorean theorem: $JL^2 + KL^2 = JK^2$, so $JL^2 + 1600 = 1681$. Then $JL^2 = 81$, and $JL = 9$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N4VSO2', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'If $f(x) = -4x + 23$, what is the value of $f(-3)$?', NULL, $lyceon_json$[{"key":"A","text":"$11$"},{"key":"B","text":"$35$"},{"key":"C","text":"$-11$"},{"key":"D","text":"$-35$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = -3$: $f(-3) = -4(-3) + 23 = 12 + 23 = 35$. The value $11$ results from evaluating $f(3) = -4(3) + 23 = -12 + 23 = 11$, ignoring the negative input. The value $-11$ comes from computing $-4(3) + 23 = 11$ and then incorrectly negating the result. The value $-35$ arises from treating $-4(-3)$ as $-12$ instead of $+12$, yielding $-12 + 23 = 11$, then applying an additional sign error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NC39AQ', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'If $\\frac{3(2x - 7)}{4} + 11 = \\frac{5x}{2}$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '23/4', ARRAY['23/4', '5.75'], E'Multiply every term by 4 to clear fractions: $3(2x - 7) + 44 = 10x$. Distribute: $6x - 21 + 44 = 10x$. Combine like terms: $6x + 23 = 10x$. Subtract $6x$ from both sides: $23 = 4x$. Divide both sides by 4: $x = \\frac{23}{4}$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PK3PMB', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $h$ is defined by $h(x) = 7x^2 - 4x + 9$. What is the value of $h(-2)$?', NULL, $lyceon_json$[{"key":"A","text":"$29$"},{"key":"B","text":"$36$"},{"key":"C","text":"$41$"},{"key":"D","text":"$45$"}]$lyceon_json$::jsonb, 'D', NULL, E'Substituting $x = -2$ into $h(x) = 7x^2 - 4x + 9$ gives $h(-2) = 7(-2)^2 - 4(-2) + 9 = 7(4) + 8 + 9 = 28 + 8 + 9 = 45$. The value $29$ results from a sign error when evaluating $-4(-2)$ as $-8$ instead of $+8$, yielding $28 - 8 + 9$. The value $36$ comes from omitting the constant term $+9$, giving only $28 + 8$. The value $41$ comes from an arithmetic slip in computing $7(4)$ as $24$ instead of $28$, yielding $24 + 8 + 9$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RJCQBY', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'The line $kx - 2y = 18$ passes through the point $(4, 3)$. A second line is perpendicular to the first and has a $y$-intercept of $7$. What is the $x$-intercept of the second line?', NULL, $lyceon_json$[{"key":"A","text":"$(-21, 0)$"},{"key":"B","text":"$(7, 0)$"},{"key":"C","text":"$(21, 0)$"},{"key":"D","text":"$(9, 0)$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $(4, 3)$ into $kx - 2y = 18$: $4k - 6 = 18$, so $4k = 24$ and $k = 6$. The first line is $6x - 2y = 18$, which gives $y = 3x - 9$ with slope $3$. The perpendicular slope is $-\\frac{1}{3}$. The second line is $y = -\\frac{1}{3}x + 7$. Setting $y = 0$: $\\frac{1}{3}x = 7$, so $x = 21$. The $x$-intercept is $(21, 0)$. The point $(-21, 0)$ results from a sign error when solving for $x$. The point $(7, 0)$ confuses the $y$-intercept of the second line with the $x$-intercept. The point $(9, 0)$ uses the absolute value of the $y$-intercept of the first line as the $x$-intercept.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TKIGLI', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'The expression $\\frac{6x^3 + 19x^2 - 7x}{2x^2 + 7x}$ can be written as $ax + b$ for all $x \\neq 0$ and $x \\neq -\\frac{7}{2}$. What is the value of $ab$?', NULL, $lyceon_json$[{"key":"A","text":"$-3$"},{"key":"B","text":"$3$"},{"key":"C","text":"$-1$"},{"key":"D","text":"$1$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor the numerator: $x(6x^2 + 19x - 7)$. To factor $6x^2 + 19x - 7$, find two numbers whose product is $6 \\cdot (-7) = -42$ and whose sum is $19$: those are $21$ and $-2$. So $6x^2 + 21x - 2x - 7 = 3x(2x + 7) - 1(2x + 7) = (3x - 1)(2x + 7)$. The numerator becomes $x(3x - 1)(2x + 7)$. Factor the denominator: $x(2x + 7)$. Canceling common factors gives $3x - 1$, so $a = 3$ and $b = -1$, and $ab = -3$. The value $3$ results from ignoring the negative sign in $b$. The values $-1$ and $1$ come from incomplete factoring of the numerator.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UB51A4', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'grid_in', E'A rectangle has a length of $13$ centimeters and a width of $9$ centimeters. What is the area, in square centimeters, of the rectangle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '117', ARRAY['117'], E'The area of a rectangle is length times width: $13 \\times 9 = 117$ square centimeters.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UMNGF3', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'grid_in', E'If $\\frac{9x^2 - 49}{3x - 7} = ax + b$ for all values of $x$ where the expression is defined, what is the value of $a + b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '10', ARRAY['10'], E'The numerator $9x^2 - 49$ is a difference of squares: $(3x)^2 - 7^2 = (3x + 7)(3x - 7)$. Dividing by $(3x - 7)$ gives $3x + 7$, so $a = 3$ and $b = 7$. Therefore $a + b = 3 + 7 = 10$.', NULL, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VOBGNJ', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'grid_in', E'What is the greatest integer value of $x$ that satisfies the inequality $-4x + 19 > 3$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'Solving $-4x + 19 > 3$ gives $-4x > -16$. Dividing both sides by $-4$ and reversing the inequality sign yields $x < 4$. The greatest integer less than $4$ is $3$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WO8NZ0', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'The equation $\\frac{5}{x - 3} + \\frac{2}{x + 1} = \\frac{29}{(x - 3)(x + 1)}$ has how many valid solutions?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"There are no valid solutions because every apparent solution is extraneous"}]$lyceon_json$::jsonb, 'B', NULL, E'Multiplying both sides by $(x - 3)(x + 1)$ gives $5(x + 1) + 2(x - 3) = 29$. Expanding: $5x + 5 + 2x - 6 = 29$, so $7x - 1 = 29$, thus $7x = 30$ and $x = \\frac{30}{7}$. Since $\\frac{30}{7} \\neq 3$ and $\\frac{30}{7} \\neq -1$, this solution is not extraneous. There is exactly $1$ valid solution. Choosing $0$ incorrectly concludes all solutions are extraneous. Choosing $2$ mistakenly assumes two solutions exist from a linear equation. The claim that every apparent solution is extraneous is false because $\\frac{30}{7}$ does not equal either restricted value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WQWJCT', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'Line $p$ has the equation $5x + 3y = 41$. Line $q$ is parallel to line $p$ and passes through the point $(7, 2)$. What is the $y$-intercept of line $q$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '41/3', ARRAY['41/3', '13.66', '13.67'], E'Rewriting line $p$ in slope-intercept form: $3y = -5x + 41$, so $y = -\\frac{5}{3}x + \\frac{41}{3}$. The slope is $-\\frac{5}{3}$. Since line $q$ is parallel, it shares this slope. Using point $(7, 2)$: $2 = -\\frac{5}{3}(7) + b$, giving $2 = -\\frac{35}{3} + b$. Then $b = 2 + \\frac{35}{3} = \\frac{6}{3} + \\frac{35}{3} = \\frac{41}{3}$. The $y$-intercept of line $q$ is $\\frac{41}{3}$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X9E45V', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on the number of hours of sunlight per day and the average daily temperature in a city over several months. The line of best fit for the data is $y = 2.7x + 31$, where $x$ is the number of hours of sunlight and $y$ is the temperature in degrees Fahrenheit. What is the best interpretation of the slope of this line?', NULL, $lyceon_json$[{"key":"A","text":"For each additional hour of sunlight, the predicted temperature increases by $2.7$ degrees Fahrenheit."},{"key":"B","text":"When there is no sunlight, the predicted temperature is $31$ degrees Fahrenheit."},{"key":"C","text":"For each additional degree Fahrenheit, the predicted sunlight increases by $2.7$ hours."},{"key":"D","text":"The temperature is always $2.7$ times the hours of sunlight."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of a line of best fit represents the predicted change in the dependent variable for each one-unit increase in the independent variable. Here, the slope is $2.7$, so for each additional hour of sunlight, the predicted temperature increases by $2.7$ degrees Fahrenheit. The interpretation about $31$ degrees with no sunlight describes the y-intercept, not the slope. The interpretation reversing the variables confuses the independent and dependent variables. The claim that temperature is always $2.7$ times the sunlight ignores the y-intercept and misrepresents a linear model as a direct proportionality.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XUB3WS', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'grid_in', E'The function $p$ is defined by $p(t) = 6 \\cdot 3^t$. What is the value of $p(0) + p(1)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '24', ARRAY['24'], E'Evaluating $p(0) = 6 \\cdot 3^0 = 6 \\cdot 1 = 6$ and $p(1) = 6 \\cdot 3^1 = 6 \\cdot 3 = 18$. Therefore $p(0) + p(1) = 6 + 18 = 24$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y0LM7E', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which expression is equivalent to $\\frac{14x^5}{7x^2}$?', NULL, $lyceon_json$[{"key":"A","text":"$2x^3$"},{"key":"B","text":"$7x^3$"},{"key":"C","text":"$2x^7$"},{"key":"D","text":"$7x^{10}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Dividing coefficients gives $\\frac{14}{7} = 2$. Subtracting exponents gives $x^{5-2} = x^3$. The result is $2x^3$. The expression $7x^3$ subtracts the coefficients instead of dividing them. The expression $2x^7$ adds the exponents instead of subtracting. The expression $7x^{10}$ both subtracts the coefficients and multiplies the exponents.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZI24N5', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'If $y = 2x + 3$ and $y = x^2 + x - 3$, what is the positive value of $x$ that satisfies both equations?', NULL, $lyceon_json$[{"key":"A","text":"$-2$"},{"key":"B","text":"$6$"},{"key":"C","text":"$3$"},{"key":"D","text":"$1$"}]$lyceon_json$::jsonb, 'C', NULL, E'Setting the equations equal: $2x + 3 = x^2 + x - 3$. Rearranging: $x^2 - x - 6 = 0$, which factors as $(x - 3)(x + 2) = 0$. The solutions are $x = 3$ and $x = -2$. Since the question asks for the positive value, $x = 3$. The value $-2$ is the negative solution. The value $6$ comes from adding the two solutions or computing the product $3 \\cdot 2$. The value $1$ does not satisfy the equation $1 - 1 - 6 \\neq 0$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZUWTXO', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'What is the value of $y$ in the solution to the system $5x + y = 23$ and $x = 3$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$8$"},{"key":"C","text":"$15$"},{"key":"D","text":"$38$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = 3$ into $5x + y = 23$ gives $5(3) + y = 23$, so $15 + y = 23$ and $y = 8$. The value $3$ is the given value of $x$, not $y$. The value $15$ is the intermediate product $5 \\times 3$ without completing the subtraction. The value $38$ results from incorrectly adding $15 + 23$ instead of subtracting.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20X9EOU', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'In 1937, the chemist Wallace Carothers patented nylon, the first entirely synthetic fiber. Nylon stockings debuted at the 1939 World''s Fair and sold out almost instantly, signaling enormous consumer demand. ______ when the United States entered World War II in 1941, nearly all nylon production was diverted to military uses such as parachutes and tire cords, leaving civilian markets with virtually no supply.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"However,"},{"key":"D","text":"In addition to this success,"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage first describes nylon''s enormous consumer success, then shifts to a contrasting outcome: wartime diversion eliminated civilian supply. "However," correctly signals this contrast between commercial triumph and sudden scarcity. "Similarly," wrongly suggests the military diversion parallels the consumer demand, but the two situations are opposites. "Nevertheless," implies an outcome that persists despite an obstacle, but the passage does not present the consumer success as an obstacle to military diversion. "In addition to this success," wrongly frames the wartime scarcity as an extension of the commercial achievement rather than a reversal of it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21A8S9Z', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 1847, Hungarian physician Ignaz Semmelweis observed that mortality rates in maternity wards dropped dramatically when doctors washed their hands before examining patients ______ his findings, however, were widely rejected by the medical establishment of his era.', $lyceon_json$[{"key":"A","text":". His"},{"key":"B","text":", his"},{"key":"C","text":"his"},{"key":"D","text":", whose"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents two independent clauses: one ending with "patients" and another beginning with "his findings." A period correctly separates these independent clauses into two sentences. Using a comma before "his" creates a comma splice between independent clauses, which is incorrect. Omitting all punctuation before "his" produces a fused sentence. Using ", whose" introduces a relative pronoun that would grammatically refer to "patients," but the findings belong to Semmelweis, not the patients, making the construction both illogical and grammatically flawed.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 65, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21M4BPV', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'The fruit fly Drosophila melanogaster has long served as a model organism in genetics research. Its genome was fully sequenced in the year 2000, and scientists have since identified the functions of thousands of its genes. ______ the fruit fly remains indispensable in laboratories studying hereditary diseases in humans.', $lyceon_json$[{"key":"A","text":"Accordingly,"},{"key":"B","text":"In other words,"},{"key":"C","text":"On the other hand,"},{"key":"D","text":"For this reason,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes the fruit fly''s long history in genetics research and the sequencing of its genome, then states that it remains indispensable in laboratories. The blank needs a transition that signals a logical consequence or continuation. "Accordingly," correctly signals that the ongoing indispensability follows from the established research value. "In other words," incorrectly suggests the final sentence is a restatement of the previous one, but it introduces a new point about current laboratory use. "On the other hand," incorrectly introduces a contrast where none exists, since the final sentence continues the same line of reasoning. "For this reason," is close but implies a narrower causal link to only the most recent sentence, whereas "Accordingly," better captures the cumulative result of both preceding facts.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
