INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW220DYBN', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, "exercised" most nearly means', E'The appellate judges exercised considerable restraint in their ruling on the redistricting challenge, declining to overturn the lower court''s findings despite vocal criticism from several advocacy organizations. Legal scholars noted that this caution reflected an institutional reluctance to intervene in matters traditionally reserved for state legislatures.', $lyceon_json$[{"key":"A","text":"practiced"},{"key":"B","text":"exerted physically"},{"key":"C","text":"alarmed"},{"key":"D","text":"trained repeatedly"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes judges who showed restraint by declining to overturn a ruling, indicating a deliberate application or employment of caution. "Practiced" captures this sense of applying or employing a quality such as restraint. "Exerted physically" relates to bodily effort, which does not fit the judicial context. "Alarmed" means to cause worry, which is unrelated to demonstrating restraint. "Trained repeatedly" refers to routine physical conditioning, which does not apply to a judicial decision to show caution.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
