INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DJHTW9', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the third paragraph in relation to the passage as a whole?', E'In 1928, the bacteriologist Frederick Griffith injected mice with a mixture of heat-killed virulent pneumococci and living avirulent pneumococci. The mice died, and Griffith recovered living virulent bacteria from their blood. He concluded that some substance from the dead cells had transformed the avirulent strain into a lethal one, a phenomenon he termed the transforming principle.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EUDSOE', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'After the civil engineer reviewed the structural assessments and consulted with the city''s planning commission, she ______ a revised proposal that addressed both the seismic safety concerns and the budgetary limitations outlined by the municipal oversight board.', $lyceon_json$[{"key":"A","text":"submits"},{"key":"B","text":"will have submitted"},{"key":"C","text":"has submitted"},{"key":"D","text":"submitted"}]$lyceon_json$::jsonb, 'D', NULL, E'The sentence describes a sequence of completed past events: the engineer "reviewed" and "consulted" (both simple past), then performed another action. Maintaining verb tense consistency requires the main clause verb to be in simple past tense as well. "Submitted" correctly continues the past-tense narrative. "Submits" incorrectly shifts to present tense, breaking the established temporal framework. "Will have submitted" shifts to future perfect, which contradicts the past-tense context. "Has submitted" uses present perfect, which is inconsistent with the "after + simple past" clause structure that signals a completed past sequence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 65, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EXP55J', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Leafcutter ants, native to Central and South American forests, do not consume the leaf fragments they harvest. Instead, these insects transport freshly cut vegetation to underground chambers where they cultivate a specialized fungus, Leucoagaricus gongylophorus, which serves as the colony''s primary food source. The ants fastidiously tend the fungal gardens, removing contaminated material and secreting antimicrobial compounds to suppress competing molds. This mutualistic arrangement, in which the ants provide substrate and protection while the fungus supplies nutrition, has persisted for approximately fifty million years.', $lyceon_json$[{"key":"A","text":"Leafcutter ants rely on a long-standing mutualistic relationship with a fungus they cultivate as their main food source"},{"key":"B","text":"The antimicrobial secretions produced by leafcutter ants have significant potential applications in modern pharmaceutical research and agricultural development"},{"key":"C","text":"Leafcutter ants are the most ecologically significant insect species found throughout Central and South American forest ecosystems today"},{"key":"D","text":"The fungus Leucoagaricus gongylophorus is completely incapable of surviving without the continuous intervention and care of leafcutter ant colonies"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how leafcutter ants cultivate a fungus for food and maintain the gardens, emphasizing the mutualistic relationship that has lasted fifty million years. The option stating that leafcutter ants rely on a long-standing mutualistic relationship with a cultivated fungus accurately captures this central idea. The claim about pharmaceutical and agricultural applications introduces topics never mentioned in the passage. The assertion that leafcutter ants are the most ecologically significant species overstates what the passage conveys. The claim that the fungus is completely incapable of surviving without ants is not stated in the passage; the text describes what the ants provide but does not assert total fungal dependence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GD5NXX', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The fruit fly Drosophila melanogaster possesses approximately 14,000 protein-coding genes, a number only modestly smaller than the roughly 20,000 found in humans. Yet fruit flies develop from egg to reproductively mature adult in just ten days, while human development spans years. This disparity suggests that the complexity of an organism''s developmental timeline is determined less by the raw number of its genes than by ________', $lyceon_json$[{"key":"A","text":"the total quantity of non-coding DNA interspersed among the organism's protein-coding sequences throughout its genome"},{"key":"B","text":"the regulatory networks that govern when and where those genes are expressed during development"},{"key":"C","text":"whether the organism reproduces sexually or asexually under natural environmental conditions"},{"key":"D","text":"the geographic range across which populations of the organism have historically been distributed"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage establishes that similar gene counts can produce vastly different developmental timelines, implying that something beyond gene count governs developmental complexity. The completion about regulatory networks controlling gene expression timing and location logically follows, since regulation determines how the same genetic toolkit produces different outcomes. The completion about non-coding DNA quantity introduces a factor the passage never discusses and conflates genome size with developmental regulation. The completion about reproductive mode is unrelated to the developmental-timeline disparity the passage highlights. The completion about geographic range concerns ecology rather than developmental biology.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GXKMKS', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'A team of ecologists proposes that the reintroduction of gray wolves to Yellowstone National Park in 1995 triggered a trophic cascade that ultimately strengthened riverbank stability. Which finding, if true, would most directly support this proposal?', E'Trophic cascades occur when the presence or absence of a top predator produces indirect effects that propagate down through multiple levels of a food web. In terrestrial systems, such cascades can extend beyond animal populations to alter vegetation structure, soil composition, and even geomorphological processes. The mechanisms linking predators to landscape-level changes, however, remain difficult to isolate because observational field studies rarely control for concurrent shifts in climate, hydrology, or human land use.', $lyceon_json$[{"key":"A","text":"Hydrological records from the United States Geological Survey indicate that annual peak discharge in the Lamar River has declined steadily since 1990, a trend consistent with reduced snowpack accumulation across the northern Rocky Mountain region rather than with any biotic alteration of the riparian watershed"},{"key":"B","text":"Genetic sampling of Yellowstone's wolf population reveals that the reintroduced animals have maintained heterozygosity levels comparable to source populations in Alberta, suggesting minimal inbreeding depression over the first seven generations"},{"key":"C","text":"Willow and cottonwood canopy cover along the Lamar River increased by 171 percent in reaches where elk browsing dropped after wolf packs established territories, while comparable reference reaches outside the park showed no change"},{"key":"D","text":"Elk calf recruitment rates in the park's northern range fell by 34 percent between 1996 and 2004, a decline attributed by wildlife managers primarily to severe winters and drought conditions rather than to predation by the newly established wolf packs"}]$lyceon_json$::jsonb, 'C', NULL, E'The proposal requires evidence connecting wolves to reduced elk browsing, increased riparian vegetation, and ultimately stronger riverbanks. The finding about increased willow and cottonwood cover in wolf-territory reaches where elk browsing dropped — with no comparable change in reference reaches — traces a causal chain from predator reintroduction through herbivore behavior to vegetation recovery, directly supporting the trophic-cascade mechanism. The finding about declining peak discharge attributes hydrological changes to reduced snowpack rather than biotic factors, undercutting the wolf-driven explanation. The finding about wolf genetic diversity addresses population health, not landscape effects. The finding about elk calf recruitment attributes the decline to weather rather than predation, which contradicts the proposed mechanism.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2H5IJNY', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of rare minerals displayed in the university''s geology hall ______ visitors from around the world who are interested in studying geological formations from the Precambrian era.', $lyceon_json$[{"key":"A","text":"attract"},{"key":"B","text":"attracts"},{"key":"C","text":"are attracting"},{"key":"D","text":"have attracted"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is "collection," which is singular, not the plural noun "minerals" within the intervening prepositional phrase "of rare minerals." A singular subject requires a singular verb. "Attracts" is the correct singular present-tense form. "Attract" is a base plural form that incorrectly agrees with "minerals" rather than the actual subject. "Are attracting" and "have attracted" both use plural auxiliary verbs that similarly fail to agree with the singular subject "collection."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JOMQI0', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Archaeologist Maria Teresa Nicoletti has argued that the obsidian tools found at the Sicilian site of Ferriere originated from the volcanic island of Pantelleria, roughly 110 kilometers away. Chemical analysis of the tools supports her claim: their strontium and barium signatures closely match samples taken from Pantelleria''s Balata dei Turchi quarry. ______ Nicoletti acknowledges that obsidian from a second source, the island of Lipari, exhibits partially overlapping trace-element profiles, a fact that complicates definitive attribution for a small subset of the artifacts.', $lyceon_json$[{"key":"A","text":"That is,"},{"key":"B","text":"Consequently,"},{"key":"C","text":"Even so,"},{"key":"D","text":"To illustrate this point further,"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage first presents evidence supporting Nicoletti''s claim about the obsidian''s origin, then introduces a complication: a second source has overlapping chemical profiles. "Even so," correctly signals a concession that qualifies the preceding evidence without entirely undermining it. "That is," wrongly suggests the final sentence restates the chemical evidence, but it actually introduces a new complicating factor. "Consequently," wrongly implies the overlapping profiles are a direct result of the matching strontium and barium signatures, when they are instead an independent complication. "To illustrate this point further," wrongly frames the Lipari complication as additional support for the Pantelleria attribution, when it actually weakens the certainty of that attribution.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2K3RE0Z', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'For decades, marine biologists assumed that coral reefs could not survive below the photic zone, the upper ocean layer penetrated by sunlight. This assumption seemed well-founded: reef-building corals depend on photosynthetic algae for energy. In 1997, however, submersible expeditions off the coast of Curacao documented thriving coral communities at depths exceeding 150 meters, far below where sunlight can sustain photosynthesis. Subsequent research revealed that these deep corals rely on chemosynthetic bacteria rather than algae, fundamentally altering scientific understanding of reef ecology.', $lyceon_json$[{"key":"A","text":"It traces the chronological development of submersible technology and its applications in marine biology"},{"key":"B","text":"It presents a long-held scientific assumption, describes a discovery that challenged it, and explains what the discovery revealed"},{"key":"C","text":"It compares two competing hypotheses about coral reef formation and argues that one is superior to the other"},{"key":"D","text":"It catalogs several types of coral species and evaluates which environments each type is best suited to inhabit"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage follows a clear three-part structure: it introduces the assumption that corals require sunlight, describes the 1997 submersible discovery of deep coral communities, and then explains that these corals use chemosynthetic bacteria. Presenting a long-held assumption, a challenging discovery, and an explanation of that discovery accurately captures this structure. The text mentions submersibles only as the vehicle for discovery, not as a focus of technological history. No two competing hypotheses are compared or evaluated against each other. The passage does not catalog multiple coral species or evaluate their environmental suitability.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KIMIZP', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'In a 2019 study, conservation biologists tracked the foraging behavior of 37 individually marked Florida scrub-jays across a fragmented landscape of sand pine scrub and suburban development. Jays whose territories bordered residential areas spent 42 percent more time in flight between foraging bouts than jays occupying interior scrub habitat, yet the border-territory jays consumed 19 percent fewer arthropods per hour. The researchers attributed the lower foraging efficiency not to reduced prey abundance at habitat edges — pitfall-trap surveys showed comparable arthropod densities — but to ________', $lyceon_json$[{"key":"A","text":"a genetic predisposition among border-territory jays to favor energy-conserving perch-and-wait hunting strategies rather than active ground foraging"},{"key":"B","text":"seasonal fluctuations in arthropod availability that disproportionately affected edge habitats during the winter months when the study was originally conducted"},{"key":"C","text":"interspecific competition from blue jays, a closely related corvid species that aggressively displaces Florida scrub-jays from productive suburban foraging sites"},{"key":"D","text":"the heightened vigilance demands imposed by novel disturbances such as domestic cats, vehicle traffic, and pedestrian activity near residential boundaries"}]$lyceon_json$::jsonb, 'D', NULL, E'The passage rules out reduced prey abundance, so the explanation must involve a behavioral factor that disrupts foraging despite adequate prey. The completion about heightened vigilance from residential disturbances logically accounts for both increased flight time and reduced prey capture: the jays spend time reacting to threats rather than foraging. The completion about genetic predisposition for perch-and-wait strategies contradicts the observation that border jays spend more time in flight. The completion about seasonal fluctuations directly contradicts the pitfall-trap data showing comparable arthropod densities. The completion about blue jay competition introduces a species and interaction not mentioned or implied in the passage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M9UCQE', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief report on teff grain and wants to introduce teff to readers who are unfamiliar with it. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2N4IEYN', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, "plastic" most nearly means', E'Nineteenth-century geologists studying mountain formation observed that certain rock layers exhibited remarkable plastic behavior when subjected to sustained tectonic pressure over millennia. Rather than fracturing outright, these strata deformed gradually, folding into elaborate arcs and troughs visible in cliff faces across the Scottish Highlands.', $lyceon_json$[{"key":"A","text":"synthetic"},{"key":"B","text":"superficial"},{"key":"C","text":"malleable"},{"key":"D","text":"transparent"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage describes rock layers that deform gradually under pressure rather than fracturing, which indicates flexibility and the capacity to be reshaped. "Malleable" captures this meaning of being capable of being shaped or bent without breaking. "Synthetic" refers to artificially manufactured material, which is unrelated to the geological context. "Superficial" means existing only on the surface, which does not match the deep structural deformation described. "Transparent" means see-through, which is irrelevant to the behavior under pressure described in the passage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2N64JEO', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Dr. Amara Osei, whose research on deep-sea bioluminescence has been cited in over two hundred peer-reviewed ______ that the light-producing mechanisms of certain abyssal organisms could inspire a new generation of energy-efficient illumination technologies.', $lyceon_json$[{"key":"A","text":"publications; argues"},{"key":"B","text":"publications argues"},{"key":"C","text":"publications, argues"},{"key":"D","text":"publications. She argues"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence has the structure "Dr. Amara Osei, [nonrestrictive clause], argues that..." The nonrestrictive clause beginning with "whose" must be closed by a comma before the main verb "argues." A comma after "publications" correctly closes the clause and connects the subject to its verb. A semicolon incorrectly treats the clause as independent and severs the subject from its predicate. Omitting punctuation after "publications" fails to close the nonrestrictive clause. A period after "publications" creates the fragment "Dr. Amara Osei, whose research... publications." because that unit lacks a main verb for the subject "Dr. Amara Osei" — the verb "has been cited" belongs to "research" inside the subordinate clause.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OBUHUS', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the overall structure of the text?', E'The fruit fly Drosophila melanogaster has been a staple of genetics research since Thomas Hunt Morgan''s laboratory experiments in the early twentieth century. Its short generation time, large number of offspring, and easily observable mutations make it an ideal model organism. <u>Despite its simplicity, the fruit fly shares roughly sixty percent of its genes with humans.</u> This genetic overlap has enabled researchers to use Drosophila studies to investigate diseases ranging from Parkinson''s to certain cancers.', $lyceon_json$[{"key":"A","text":"It introduces a surprising fact that explains why subsequent research applications are possible"},{"key":"B","text":"It provides historical background on the discovery of the fruit fly as a research tool"},{"key":"C","text":"It lists the specific diseases that fruit fly research has helped to cure"},{"key":"D","text":"It qualifies an earlier claim by noting limitations of the model organism"}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence presents an unexpected detail (genetic similarity between fruit flies and humans despite the organism''s apparent simplicity) that directly sets up the following sentence about disease research applications. Introducing a surprising fact that explains why subsequent research is possible accurately captures this structural role. The historical background about Morgan''s laboratory appears earlier in the passage, not in the underlined sentence. The passage mentions diseases but does not claim they have been cured. The underlined sentence does not qualify or limit an earlier claim; rather, it adds an enabling fact.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 55, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2R9M40Y', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a paper about architect Lina Bo Bardi and wants to emphasize how Bo Bardi''s design philosophy differed from the prevailing modernist approach. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RKZGA7', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Archaeologists studying the Late Bronze Age site of Uluburun, off the southwestern coast of Turkey, recovered over 350 copper oxhide ingots from a single shipwreck dated to approximately 1300 BCE. Lead-isotope analysis traced the majority of the ingots to mines on Cyprus, but a subset of 47 ingots exhibited isotopic signatures consistent with ore deposits in the Lavrion district of Attica, mainland Greece. The vessel also carried Canaanite amphorae, Mycenaean pottery, Egyptian scarabs, and Baltic amber beads. Taken together, these findings suggest that Late Bronze Age maritime commerce ________', $lyceon_json$[{"key":"A","text":"was controlled exclusively by Cypriot merchant fleets that monopolized copper distribution and permitted only limited participation by other regional trading powers in the Mediterranean basin"},{"key":"B","text":"remained confined to short-distance, coastal cabotage routes connecting neighboring port cities rather than spanning the full breadth of the eastern Mediterranean and adjacent regions"},{"key":"C","text":"operated through decentralized, multi-origin trading networks that integrated materials and goods from geographically dispersed sources across the eastern Mediterranean and beyond"},{"key":"D","text":"depended primarily on overland caravan routes through Anatolia, with seaborne transport serving as an auxiliary means of redistributing surplus goods between major inland market centers"}]$lyceon_json$::jsonb, 'C', NULL, E'The cargo includes copper from two different sources (Cyprus and mainland Greece), pottery from multiple cultures (Canaanite, Mycenaean, Egyptian), and amber from the distant Baltic region. This diversity of origins on a single vessel most logically supports the inference that trade networks were decentralized and drew from geographically dispersed sources. The claim of exclusive Cypriot control contradicts the evidence of Greek-origin ingots and multi-cultural cargo. The claim that trade was confined to short coastal routes is incompatible with the presence of Baltic amber, which required long-distance exchange. The claim about dependence on overland caravan routes is contradicted by the evidence itself: a seagoing vessel carrying the cargo.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SIVR60', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'A musicologist claims that the tuning system used in Baroque-era keyboard instruments influenced composers to favor certain key signatures over others. Which finding, if true, would most directly support this claim?', E'During the Baroque period (roughly 1600–1750), most keyboard instruments were tuned using meantone temperament, a system that produced pure-sounding thirds in commonly used keys but created noticeably dissonant intervals — known as wolf intervals — in remote keys such as G-sharp minor and D-sharp minor. Equal temperament, which distributes the slight impurity evenly across all twelve keys, did not become the dominant tuning standard for keyboards until the nineteenth century.', $lyceon_json$[{"key":"A","text":"Letters exchanged between J. S. Bach and organ builders in Leipzig document disputes over maintenance schedules and the cost of replacing worn bellows components"},{"key":"B","text":"A comprehensive catalog of Baroque keyboard works reveals that over 87 percent were composed in keys with two or fewer sharps or flats, with virtually none in wolf-interval keys"},{"key":"C","text":"Acoustic measurements confirm that modern concert grand pianos tuned to equal temperament produce intervals differing from pure ratios by no more than two cents in any key"},{"key":"D","text":"Music theorists in eighteenth-century Paris published treatises advocating for expanded chromatic vocabulary regardless of the tuning conventions prevailing at the time of composition"}]$lyceon_json$::jsonb, 'B', NULL, E'The claim is that meantone temperament''s limitations steered composers toward certain key signatures. A catalog showing the vast majority of Baroque keyboard works avoided keys producing wolf intervals directly links the tuning system to compositional choices. The finding about Bach''s correspondence with organ builders concerns instrument maintenance, not key-signature selection. The finding about modern pianos and equal temperament describes a different era''s tuning system and does not address Baroque compositional patterns. The finding about Parisian theorists advocating expanded chromaticism actually undermines rather than supports the claim that tuning constrained key choices.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TBO7CG', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Researchers hypothesize that elevated soil salinity near coastal wetlands reduces the germination rate of Spartina patens seeds. Which finding, if true, would most directly support this hypothesis?', E'Spartina patens, commonly known as saltmeadow cordgrass, is a perennial grass that colonizes the upper margins of tidal salt marshes along the Atlantic coast of North America. Although mature plants tolerate moderate salinity through specialized salt-excreting glands, the species'' seedlings are considered more vulnerable to osmotic stress during the earliest stages of development.', $lyceon_json$[{"key":"A","text":"Spartina patens populations have declined across several mid-Atlantic marshes during a recent period of rising average annual temperatures and altered precipitation patterns"},{"key":"B","text":"Field surveys indicate that Spartina patens is most abundant in zones where tidal inundation occurs fewer than three times per month during the peak growing season"},{"key":"C","text":"Genetic analysis reveals that coastal populations of Spartina patens exhibit greater allelic diversity at loci associated with osmotic regulation than inland populations"},{"key":"D","text":"Seeds planted in soil with a salinity of 18 parts per thousand germinated at 23 percent, compared with 81 percent for seeds in non-saline soil under identical conditions"}]$lyceon_json$::jsonb, 'D', NULL, E'The hypothesis specifically links elevated soil salinity to reduced germination rates. The finding showing a stark difference in germination rates between saline and non-saline soil under controlled conditions directly supports this causal claim. The finding about population decline and changing climate does not isolate salinity as a factor. The finding about tidal inundation frequency relates to plant abundance patterns rather than germination under saline conditions. The finding about allelic diversity at osmotic-regulation loci suggests adaptation to salinity but does not address germination rates.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TM05MG', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, "tempered" most nearly means', E'The glassblower''s ambitions were tempered by the practical realities of running a small studio. Rising material costs and limited kiln space meant that large-scale installations, however appealing, remained out of reach for the foreseeable future.', $lyceon_json$[{"key":"A","text":"heated"},{"key":"B","text":"moderated"},{"key":"C","text":"hardened"},{"key":"D","text":"provoked"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes how the glassblower''s ambitions were constrained by practical realities such as rising costs and limited space. "Moderated" captures this sense of restraint. "Heated" and "hardened" relate to metallurgical or glassworking processes for the word "temper" but do not fit the context of limiting ambitions. "Provoked" means to incite or stimulate, which is the opposite of the restraint described in the passage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WA66CW', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'The economist Elinor Ostrom challenged the prevailing orthodoxy that common-pool resources inevitably suffer from overexploitation unless privatized or managed by a central authority. Through extensive fieldwork in settings as varied as Swiss alpine meadows and Philippine irrigation systems, Ostrom documented communities that had sustained shared resources for centuries through locally devised rules. <u>These rules were neither imposed by external regulators nor derived from theoretical models of rational self-interest.</u> Instead, they emerged organically from the communities'' own negotiations, trial and error, and accumulated local knowledge, suggesting that the capacity for self-governance had been systematically underestimated by mainstream economic theory.', $lyceon_json$[{"key":"A","text":"It concedes that Ostrom's fieldwork had certain methodological limitations that later researchers would need to address"},{"key":"B","text":"It specifies the two explanatory frameworks that Ostrom's findings implicitly argue against, sharpening the contrast with what follows"},{"key":"C","text":"It summarizes the central recommendation Ostrom made to policymakers based on her fieldwork observations"},{"key":"D","text":"It provides an example of a specific Swiss alpine community that successfully managed its shared grazing lands"}]$lyceon_json$::jsonb, 'B', NULL, E'The underlined sentence identifies two sources the community rules did not come from: external regulators (central authority) and theoretical models of rational self-interest (privatization logic). By ruling out both orthodox explanations, the sentence sharpens the contrast with the next sentence, which reveals the actual organic origin of the rules. Specifying the two explanatory frameworks that the findings argue against accurately describes this rhetorical function. The sentence does not acknowledge any limitation of Ostrom''s methods. It makes no policy recommendation. It does not describe any specific community; the Swiss meadows are mentioned earlier in the passage as part of the fieldwork settings.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2X71YRQ', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'According to the text, what is the primary reason the researchers revised their initial classification of Tiktaalik roseae?', E'When paleontologists first described Tiktaalik roseae in 2006, they classified its pectoral fin skeleton as a straightforward intermediate between fish fins and tetrapod limbs. Subsequent micro-CT scanning of the specimen in 2014, however, revealed a previously undetected network of small radial bones embedded within the fin''s fleshy base. These radials bore load-distributing features comparable to those in the wrists of early tetrapods such as Acanthostega, suggesting that Tiktaalik possessed a degree of weight-bearing capability exceeding what the original analysis had proposed. Consequently, the research team reclassified the fin as exhibiting a more advanced stage of the fin-to-limb transition than their 2006 description had indicated.', $lyceon_json$[{"key":"A","text":"Genetic evidence demonstrated that Tiktaalik was more closely related to Acanthostega than any other known tetrapod fossil in the geological record"},{"key":"B","text":"Micro-CT scanning uncovered radial bones with load-distributing features that indicated greater weight-bearing capability than originally recognized"},{"key":"C","text":"Field excavations at the original discovery site on Ellesmere Island yielded additional Tiktaalik specimens preserving detailed soft tissue impressions"},{"key":"D","text":"Comparative anatomical studies of living lungfish showed that the fin structure identified in the 2006 description was a common trait rather than transitional"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage explicitly states that micro-CT scanning revealed a network of radial bones with load-distributing features comparable to early tetrapod wrists, prompting the reclassification. The option about micro-CT scanning and radial bones directly matches this stated reason. The option referencing genetic evidence and Acanthostega introduces information not present in the text. The option about additional specimens and soft tissue impressions fabricates details absent from the passage. The option about lungfish comparative studies contradicts the passage''s framing of the fin as transitional rather than common.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YB3NLC', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the persistent drought conditions that have devastated farmland across the southern provinces nor the recent outbreak of a previously unknown crop ______ deterred the agricultural cooperative from proceeding with its plan to expand sunflower cultivation into three additional districts next season.', $lyceon_json$[{"key":"A","text":"blight have"},{"key":"B","text":"blight has"},{"key":"C","text":"blight, having"},{"key":"D","text":"blight that has"}]$lyceon_json$::jsonb, 'B', NULL, E'In a "neither...nor" construction, the verb must agree in number with the subject closer to the verb. The nearer subject is "the recent outbreak," which is singular, so the verb must be singular: "has." "Blight have" uses a plural verb that incorrectly agrees with the more distant plural subject "conditions" rather than the closer singular "outbreak." "Blight, having" replaces the finite verb with a participial phrase, leaving the entire "neither...nor" construction without a main predicate and producing a sentence fragment. "Blight that has" turns "that has deterred" into a relative clause modifying "blight," which strips the sentence of its main verb and likewise produces a fragment.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YWI0OL', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Entomologist Clara Voss discovered a previously unknown species of beetle in the cloud forests of northern Ecuador ______ the insect, which measures just three millimeters in length, produces a bioluminescent glow visible only in complete darkness.', $lyceon_json$[{"key":"A","text":"the"},{"key":"B","text":", the"},{"key":"C","text":". The"},{"key":"D","text":", being the"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage contains two independent clauses: one ending with "Ecuador" and another beginning with "the insect." Two independent clauses require proper separation. A period followed by a capitalized "The" correctly separates these clauses into distinct sentences. Using no punctuation (just "the") creates a fused sentence, which violates Standard English conventions. Using only a comma before "the" creates a comma splice, which is also incorrect. Using ", being the" produces a nonsensical participial phrase that fails to logically connect to the second clause.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
